#!/usr/bin/env python3
# Exact finite certificate; Python standard library only.
from itertools import product
import hashlib

I = range(2, 7)
B = range(1, 6)
CASES = [(p, c) for p in B for c in B if min(p, c) == 1]

def partitions_of(n, maxpart, maxlen, ceiling=None):
    out = []
    def rec(rem, upper, acc):
        if rem == 0:
            out.append(tuple(acc)); return
        if len(acc) == maxlen:
            return
        for x in range(min(upper, maxpart, rem), 0, -1):
            rec(rem-x, x, acc+[x])
    rec(n, maxpart, [])
    return out

def inside(lam, q, r):
    return len(lam) <= r and (not lam or lam[0] <= q)

def contains(mu, lam):
    return all((mu[k] if k < len(mu) else 0) >= x for k, x in enumerate(lam))

def conj(lam, q):
    return tuple(sum(x >= col for x in lam) for col in range(1, q+1))

def horizontal(mu, lam, q):
    if not contains(mu, lam): return False
    cm, cl = conj(mu, q), conj(lam, q)
    return all(a-b <= 1 for a, b in zip(cm, cl))

def pieri(lam, k, q, r):
    n = sum(lam) + k
    return {mu for mu in partitions_of(n, q, r) if horizontal(mu, lam, q)}

def D3(a):
    return (a[0][0]*(a[1][1]*a[2][2]-a[1][2]*a[2][1])
            -a[0][1]*(a[1][0]*a[2][2]-a[1][2]*a[2][0])
            +a[0][2]*(a[1][0]*a[2][1]-a[1][1]*a[2][0]))

def D2(a):
    return a[0][0]*a[1][1]-a[0][1]*a[1][0]

checked = 0
for i, j, p, c in product(I, I, B, B):
    if min(p, c) != 1: continue
    q, r, d = i+p, j+c, i*j
    x0 = (i,)*j
    x1 = (i+1,)+(i,)*(j-1)
    y1 = (i,)*j+(1,)
    x2 = (i+1, i+1)+(i,)*(j-2)
    z  = (i+1,)+(i,)*(j-1)+(1,)
    y2 = (i,)*j+(2,)
    gamma = (i+2,)+(i,)*(j-1) if p >= 2 else None
    theta = (i,)*j+(1,1) if c >= 2 else None

    # Complete degree columns containing i^j.
    got1 = {mu for mu in partitions_of(d+1, q, r) if contains(mu, x0)}
    exp1 = {x1, y1}
    got2 = {mu for mu in partitions_of(d+2, q, r) if contains(mu, x0)}
    exp2 = {x2, z, y2} | ({gamma} if gamma else set()) | ({theta} if theta else set())
    assert got1 == exp1, (i,j,p,c,'columns d+1',got1,exp1)
    assert got2 == exp2, (i,j,p,c,'columns d+2',got2,exp2)

    # Exact conditional Pieri identities, represented as equality of Schur supports.
    assert pieri(x0, 1, q, r) == {x1, y1}
    assert pieri(x0, 2, q, r) == ({x2,z,y2} | ({gamma} if gamma else set()))
    assert pieri(x1, 1, q, r) == ({x2,z} | ({gamma} if gamma else set()))
    assert pieri(y1, 1, q, r) == ({z,y2} | ({theta} if theta else set()))

    # Exact complementary-minor checks for the three allowed boundary regimes.
    if p == 1 and c == 1:
        # columns (x2,z,y2); selected rows h2*x0,h1*x1; complement (z,y2)
        assert D2(((1,1),(1,0))) == -1
    elif p == 1:
        # columns (x2,z,y2,theta), retain x2; rows h2*x0,h1*x1,h1*y1
        assert D3(((1,1,0),(1,0,0),(1,1,1))) == -1
    else:
        # columns (gamma,x2,z,y2), retain x2; rows h2*x0,h1*x1,h1*y1
        assert D3(((1,1,1),(1,1,0),(0,1,1))) == 1
    checked += 1

print('INPUTS: i,j=2..6; p,c=1..5; min(p,c)=1')
print('CASES_CHECKED:', checked)
print('CHECKS: degree-d+1/d+2 columns; four Pieri supports; boundary complementary determinants')
print('RESULT: PASS')
print('EXIT_STATUS: 0')
